var EXTRA=[{dot:"green",j:"Annals of Internal Medicine",h:"Commento al trial SUPER, nello stesso numero: titolo sui «decenni perduti» di cura dopo il LCA",v:"Testo di commento con il titolo «A SUPER Way to Avoid the Lost Decades of Care After Anterior Cruciate Ligament Reconstruction»; l'abstract non è disponibile e il contenuto non è stato letto, quindi si segnala solo l'esistenza.",pmid:'42804771',doi:'10.7326/ANNALS-26-03792',temi:["riabilitazione","LCA","sintomi persistenti"]},{dot:"green",j:"Arthroscopy",h:"La fiducia nel ginocchio dopo il LCA: che cosa significa davvero",v:"Commento editoriale: la mancanza di fiducia persistente si associa a esiti peggiori, ma può nascondere timori diversi (nuova lesione, funzione, prestazione) che vanno distinti in riabilitazione.",pmid:'42799329',doi:'10.1002/arj.70648',temi:["ritorno allo sport","aspetti psicologici","LCA"]},{dot:"green",j:"Arthroscopy",h:"L'altezza rotulea: meglio tenerla semplice, commento sull'affidabilità delle misure",v:"Commento editoriale che colloca gli indici di altezza rotulea dentro un approccio «à la carte» alla stabilizzazione femoro-rotulea, in cui contano altezza, troclea e posizione della tuberosità.",pmid:'42803659',doi:'10.1002/arj.70571',temi:["rotula","instabilità femoro-rotulea","MPFL"]},{dot:"green",j:"Arthroscopy Techniques",h:"Ricostruzione indipendente del legamento antero-laterale con gracile peduncolato, in due fasci",v:"Nota tecnica da Lione: il ALL viene ricostruito con un gracile peduncolato, indipendentemente dal LCA, passando sotto la benderella ileotibiale; nessun dato clinico nell'abstract.",pmid:'42801056',doi:'10.1002/atn2.70044',temi:["rinforzo laterale","ALL","LCA"]},{dot:"gray",j:"Osteoarthritis and Cartilage",h:"Lettera sul comparatore dello studio INKA: il confronto con l'unicompartimentale",v:"Una lettera discute se un comparatore arricchito di protesi monocompartimentali nello studio INKA cambi la conclusione di non inferiorità; abstract non disponibile.",pmid:'42805398',doi:'10.1016/j.joca.2026.09.010',temi:["protesi monocompartimentale","non inferiorità","studi clinici"]},{dot:"gray",j:"International Orthopaedics",h:"Il primo decennio del registro nazionale irlandese di protesi d'anca e ginocchio",v:"Analisi descrittiva di dati aggregati del registro (2015-2024): attività, fissazione, punteggi riferiti dal paziente; gli autori avvertono che la copertura nazionale è incompleta.",pmid:'42803958',doi:'10.1007/s00264-026-07044-2',temi:["registri","protesi di ginocchio","sorveglianza"]},{dot:"gray",j:"Journal of Knee Surgery",h:"Glicemia dopo la protesi di ginocchio e complicanze a cinque anni, da un database",v:"Coorte retrospettiva su database multicentrico, con appaiamento per propensione: confronta pazienti con emoglobina glicata bassa o alta uno-due anni dopo la protesi; le associazioni non provano una causa.",pmid:'42805263',doi:'10.1055/a-2968-6258',temi:["diabete","protesi di ginocchio","complicanze"]},{dot:"gray",j:"Pain Management Nursing",h:"Profilo del dolore cronico dopo protesi di ginocchio, coorte prospettica infermieristica",v:"Studio infermieristico su un piccolo gruppo di pazienti: il dolore cala nei primi mesi, con componenti sensoriale e affettiva analizzate separatamente; i predittori del dolore cronico sono esplorativi.",pmid:'42805804',doi:'10.1016/j.pmn.2026.08.019',temi:["dolore cronico","protesi di ginocchio","esiti riferiti"]},{dot:"gray",j:"Archives of Orthopaedic and Trauma Surgery",h:"Tutori per il collaterale mediale: molta variabilità nella resistenza al valgo, su banco",v:"Prova meccanica su nove tutori disponibili in commercio: la rigidità varia in modo marcato fra i dispositivi; non è una prova di efficacia clinica.",pmid:'42802206',doi:'10.1007/s00402-026-06519-6',temi:["collaterale mediale","tutori","biomeccanica"]},{dot:"gray",j:"Acta Ortopédica Brasileira",h:"Laccio emostatico e protesi robotica: nessuna differenza su perdita ematica e durata",v:"Studio retrospettivo, pubblicato su una rivista brasiliana, su protesi di ginocchio con assistenza robotica, con e senza laccio; nessuna trasfusione necessaria in nessun paziente, ma con campione limitato.",pmid:'42799285',doi:'10.1590/1413-785220263402e290496',temi:["protesi robotica","laccio emostatico","perdita ematica"]},{dot:"gray",j:"Pain Physician",h:"Nanofat o plasma ricco di piastrine nell'artrosi unilaterale: coorte retrospettiva indiana",v:"Confronto retrospettivo in una clinica del dolore, con follow-up di sei mesi: gruppi non randomizzati, quindi il confronto resta esplorativo.",pmid:'42804315',doi:'',temi:["artrosi","PRP","terapie rigenerative"]},{dot:"gray",j:"Pain Physician",h:"Prolozone contro corticosteroide e placebo nell'artrosi grave: trial randomizzato indiano",v:"Trial in doppio cieco su iniezione intra-articolare di destrosio, ozono e magnesio contro corticosteroide e soluzione salina; l'abstract non permette da solo di giudicare il peso clinico del risultato.",pmid:'42804311',doi:'',temi:["artrosi","infiltrazioni","trial randomizzato"]}];
var SCOPERTE=[{t:"Il chirurgo scozzese che nel 1784 ottenne un'anestesia regionale con un compressore di ferro sul nervo",v:"Un'analisi storica su James Moore, che prima dell'etere pubblicò il primo libro inglese interamente dedicato all'anestesia e ne descrisse una tecnica per il nervo dell'arto inferiore, usata in un'amputazione sotto il ginocchio insieme a John Hunter. Vale la deviazione perché racconta come una tecnica chirurgica nasca in silenzio e venga riscoperta, con il ritrovamento recente dello strumento originale in Scozia.",pmid:'42799651',doi:'10.1177/0310057X261486481',temi:["storia di una tecnica","anestesia regionale"]},{t:"Stampare la cartilagine e l'osso insieme: la rassegna sui supporti osteocondrali multimateriale",v:"Una rassegna di biofabbricazione sui supporti osteocondrali stampati con più materiali, con gradienti fra cartilagine e osso, vascolarizzazione e immunomodulazione, e sulle barriere che frenano il passaggio in clinica (disadattamento meccanico, stabilità nel tempo, scalabilità, regolamentazione). Vale la deviazione perché mostra dove l'ingegneria dei tessuti punta a risolvere ciò che oggi le tecniche cliniche non risolvono bene, la giunzione fra cartilagine e osso.",pmid:'42803575',doi:'10.1039/d6mh01311b',temi:["bioingegneria","cartilagine","osteocondrale"]},{t:"Un sistema di cattura del movimento per lo squat: bastano tre ripetizioni invece di cinque?",v:"Uno studio su dieci adulti sani valuta se tre ripetizioni di squat, riprese con un sistema di video 3D (MAI Motion), diano gli stessi dati cinematici di cinque. Vale la deviazione perché riguarda quanto poco basta per misurare il movimento con un sistema di cattura, un terreno adiacente ai test funzionali di rientro allo sport; il campione è piccolo e i soggetti sono sani, quindi il risultato è metodologico.",pmid:'42801190',doi:'10.7759/cureus.115292',temi:["biomeccanica","cattura del movimento","test funzionali"]}];
var SOC={"1": {"video": "Oggi parliamo di che cosa succede a chi, anche un anno o due dopo l'operazione di legamento crociato anteriore, continua ad avere sintomi al ginocchio. Uno studio randomizzato su 184 giovani adulti ha confrontato quattro mesi di esercizi seguiti dal fisioterapista, con educazione, contro una sola sessione informativa più un programma da fare da soli. A quattro mesi il questionario sul ginocchio migliorava di circa cinque punti in più con il programma seguito, e la forza della coscia cresceva di più. Il punto onesto: dopo un anno la differenza si era ridotta, perché anche il gruppo di confronto era migliorato, e i partecipanti sapevano a quale gruppo appartenevano. Un segnale utile per chi ha sintomi persistenti, non una promessa.", "linkedin": "RCT a gruppi paralleli (Culvenor, Bruder, West et al., Annals of Internal Medicine, settembre 2026) su 184 giovani adulti con problemi persistenti 9-36 mesi dopo la ricostruzione del LCA: 4 mesi di esercizio terapeutico supervisionato con educazione (SUPER) contro una singola sessione educativa con esercizio autogestito. KOOS composito a 4 mesi: +14,1 contro +9,4 punti (differenza aggiustata 4,8; IC 95% 1,4-8,2); guadagni di forza e valutazione globale di cambiamento migliori con SUPER; a 12 mesi le differenze si riducono per il miglioramento del controllo; nessuna differenza nella cartilagine alla RM. Limiti dichiarati: partecipanti non in cieco, esito riferito dal paziente.", "instagram": "🦵 Sintomi al ginocchio anche dopo l'operazione al crociato? Gli esercizi seguiti da un fisioterapista hanno dato un vantaggio.\n\nIn uno studio randomizzato su 184 giovani adulti con problemi persistenti da 9 a 36 mesi dopo l'operazione, quattro mesi di esercizi guidati con educazione hanno portato un miglioramento del questionario sul ginocchio di circa cinque punti in più rispetto a una sola sessione informativa.\n\nIl limite: dopo un anno la differenza si era ridotta, e i partecipanti sapevano a quale gruppo appartenevano.", "pazienti": "Non tutti stanno bene dopo l'operazione di legamento crociato anteriore: alcune persone continuano ad avere dolore, gonfiore o insicurezza nel ginocchio per anni. Uno studio randomizzato pubblicato su una rivista di medicina interna ha seguito 184 giovani adulti in questa situazione, da 9 a 36 mesi dopo l'operazione.\n\nMetà ha seguito quattro mesi di esercizi con un fisioterapista, due volte a settimana, con informazioni sul ginocchio; l'altra metà ha ricevuto una sola spiegazione e un programma da fare da soli. Dopo quattro mesi il primo gruppo stava meglio, con un miglioramento del questionario sul ginocchio più alto di circa cinque punti, e aveva recuperato più forza nella coscia.\n\nDopo un anno la differenza era più piccola, perché anche il secondo gruppo era migliorato. Lo studio non dice quindi che gli esercizi guidati siano indispensabili, ma che possono accelerare il miglioramento; e i partecipanti sapevano a quale gruppo appartenevano, un limite da tenere presente."}};
var SOCV={"1": {"video": {"chir": ["RCT a gruppi paralleli (Culvenor, Bruder, West et al., Annals of Internal Medicine, settembre 2026): 184 giovani adulti con problemi persistenti 9-36 mesi dopo ricostruzione del LCA, 92 per braccio. Programma SUPER di quattro mesi, esercizio terapeutico supervisionato due volte a settimana con educazione, contro una singola sessione educativa più una risorsa di esercizio autogestito. Esito primario la variazione del KOOS composito a quattro mesi.", "A quattro mesi il KOOS migliora di 14,1 punti con SUPER contro 9,4 nel controllo, differenza media aggiustata 4,8; IC 95% da 1,4 a 8,2. Maggiori guadagni di forza e più successi alla valutazione globale di cambiamento, per il dolore 73% contro 40%. A dodici mesi le differenze si riducono perché il controllo continua a migliorare, mentre i guadagni di SUPER si mantengono; nessuna differenza nella cartilagine alla RM.", "I limiti: partecipanti non in cieco, esito primario riferito dal paziente, limite inferiore dell'IC basso sulla scala da 0 a 100, tipo di innesto non riportato nell'abstract, testo completo non disponibile. Per T3 il messaggio è misurato: la forza del quadricipite ben oltre i sei mesi resta un bersaglio trattabile, ma questo trial non dimostra che il rinforzo tardivo cambi la storia dell'articolazione."], "misto": ["Uno studio randomizzato su 184 giovani adulti ha seguito chi, da nove a trentasei mesi dopo l'operazione di legamento crociato anteriore, aveva ancora sintomi al ginocchio. Metà ha fatto quattro mesi di esercizi con un fisioterapista, due volte a settimana, con educazione; l'altra metà una sola sessione informativa più un programma da fare da soli.", "A quattro mesi il punteggio del questionario sul ginocchio è migliorato di quasi cinque punti in più nel gruppo seguito dal fisioterapista, con margine di incertezza da uno virgola quattro a otto virgola due punti. Anche la forza della coscia è cresciuta di più, e più persone hanno riferito un miglioramento del dolore: il settantatré per cento contro il quaranta per cento.", "Il limite va detto per esteso: dopo un anno la differenza si era ridotta, perché anche il gruppo di confronto era migliorato con il tempo, e i partecipanti sapevano a quale gruppo appartenevano. Sulla struttura della cartilagine alla risonanza non si è vista nessuna differenza. Per chi ha sintomi persistenti è un segnale utile, non una promessa."], "pazienti": ["Non tutti stanno bene dopo l'operazione di legamento crociato: alcune persone continuano ad avere dolore o insicurezza nel ginocchio per anni. Uno studio su 184 giovani adulti, da nove a trentasei mesi dopo l'intervento, ha confrontato due modi di occuparsene.", "Metà ha fatto quattro mesi di esercizi con un fisioterapista, due volte a settimana. L'altra metà ha ricevuto una sola spiegazione con un programma da fare da soli. Dopo quattro mesi il primo gruppo stava meglio, con un miglioramento del questionario sul ginocchio più alto di circa cinque punti, e la forza della coscia era cresciuta di più.", "Dopo un anno, però, la differenza era più piccola, perché anche chi faceva gli esercizi da solo era migliorato. Lo studio non dice che gli esercizi guidati siano indispensabili, ma che possono dare un vantaggio nei primi mesi. Chi ha sintomi persistenti può parlarne con il proprio chirurgo o fisioterapista."]}, "linkedin": {"chir": ["RCT (Culvenor, Bruder, West et al., Annals of Internal Medicine, settembre 2026), 184 giovani adulti con problemi persistenti 9-36 mesi dopo ricostruzione del LCA: 4 mesi di esercizio supervisionato con educazione (SUPER) contro una sola sessione educativa con esercizio autogestito.", "KOOS composito a 4 mesi: +14,1 contro +9,4 punti (differenza aggiustata 4,8; IC 95% 1,4-8,2); più forza e più risposte favorevoli alla valutazione globale con SUPER; a 12 mesi differenze ridotte, nessuna differenza nella cartilagine alla RM.", "Limiti dichiarati: partecipanti non in cieco, esito primario riferito dal paziente; tipo di innesto non riportato nell'abstract; testo completo non aperto."], "misto": ["Studio randomizzato su 184 giovani adulti con sintomi persistenti da 9 a 36 mesi dopo l'operazione di legamento crociato: quattro mesi di esercizi seguiti dal fisioterapista contro una sola sessione informativa.", "A quattro mesi il questionario sul ginocchio migliora di quasi cinque punti in più con il programma seguito (margine di incertezza da 1,4 a 8,2); anche la forza della coscia cresce di più.", "A un anno la differenza si riduce, perché il gruppo di confronto migliora nel tempo; i partecipanti sapevano a quale gruppo appartenevano."], "pazienti": ["Uno studio su 184 giovani adulti con sintomi persistenti dopo l'operazione di legamento crociato ha confrontato quattro mesi di esercizi con un fisioterapista e una sola sessione informativa.", "Dopo quattro mesi chi aveva fatto gli esercizi guidati stava meglio e aveva più forza nella coscia.", "Dopo un anno la differenza era più piccola: lo studio indica un vantaggio nei primi mesi, non una soluzione definitiva."]}, "instagram": {"chir": ["🦵 Sintomi persistenti dopo LCA: RCT su 184 giovani adulti, KOOS a 4 mesi +14,1 con esercizio supervisionato contro +9,4 (differenza 4,8; IC 95% 1,4-8,2).", "A 12 mesi il divario si riduce: il controllo continua a migliorare.", "Limiti: non in cieco, esito riferito dal paziente."], "misto": ["🦵 Sintomi al ginocchio dopo il crociato? Studio su 184 giovani adulti: esercizi con fisioterapista per 4 mesi, vantaggio nei primi mesi.", "Dopo un anno la differenza si riduce: anche il gruppo di confronto migliora.", "Limite: i partecipanti sapevano a quale gruppo appartenevano."], "pazienti": ["🦵 Ancora sintomi al ginocchio dopo l'operazione al crociato? Gli esercizi con un fisioterapista hanno dato un vantaggio nei primi mesi.", "Dopo un anno la differenza era più piccola: anche chi faceva gli esercizi da solo migliorava.", "Ne puoi parlare con il tuo chirurgo o fisioterapista."]}, "reel": {"chir": ["[SINTOMI PERSISTENTI DOPO LCA] RCT, 184 giovani adulti: KOOS a 4 mesi +4,8 punti con esercizio supervisionato (IC 95% 1,4-8,2).", "[A 12 MESI] Divario ridotto: il controllo continua a migliorare; nessuna differenza in cartilagine alla RM.", "[IL LIMITE] Non in cieco, esito riferito dal paziente."], "misto": ["[DOPO IL CROCIATO, ANCORA SINTOMI?] 184 giovani adulti: esercizi con fisioterapista per 4 mesi, vantaggio nei primi mesi.", "[A UN ANNO] La differenza si riduce: anche il gruppo di confronto migliora.", "[IL LIMITE] I partecipanti sapevano a quale gruppo appartenevano."], "pazienti": ["[ANCORA SINTOMI DOPO IL CROCIATO?] Gli esercizi con un fisioterapista hanno aiutato nei primi mesi.", "[DOPO UN ANNO] La differenza era più piccola: anche gli altri miglioravano.", "[IN PRATICA] Ne puoi parlare con il tuo chirurgo o fisioterapista."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #Riabilitazione", "instagram": "#ortopedia #legamentocrociato #lca #fisioterapia #riabilitazione #ginocchio #chirurgiadelginocchio #medicinasportiva #sportsmedicine", "kw": "legamento crociato dopo operazione, fisioterapia ginocchio, sintomi persistenti ginocchio"}};
var NLB={"1": {"prof": ["LCA e sintomi persistenti: a 4 mesi l'esercizio supervisionato supera la sola educazione", "Un RCT su 184 giovani adulti con problemi persistenti 9-36 mesi dopo la ricostruzione del LCA mostra che 4 mesi di esercizio supervisionato con educazione migliorano il KOOS composito di 4,8 punti in più rispetto a una sola sessione educativa con esercizio autogestito (IC 95% 1,4-8,2); a 12 mesi la differenza si riduce, e la cartilagine alla RM non differisce.", "Nota critica: partecipanti non in cieco, esito riferito dal paziente, limite inferiore dell'IC basso sulla scala 0-100 e tipo di innesto non riportato nell'abstract."], "mix": ["Dopo il crociato, un programma di esercizi con il fisioterapista aiuta chi ha ancora sintomi", "In uno studio randomizzato su 184 giovani adulti con dolore o limitazioni persistenti da 9 a 36 mesi dopo l'operazione al legamento crociato, quattro mesi di esercizi seguiti dal fisioterapista con educazione hanno portato un miglioramento del questionario sul ginocchio maggiore di circa cinque punti rispetto a una sola sessione informativa. Dopo un anno la differenza si è ridotta, perché anche il gruppo di confronto ha continuato a migliorare.", "Nota sul limite: i partecipanti sapevano a quale gruppo appartenevano e l'esito è riferito da loro stessi; il vantaggio a quattro mesi ha un margine di incertezza ampio."], "paz": ["Sintomi dopo il crociato: gli esercizi guidati hanno dato un vantaggio nei primi mesi", "Alcuni giovani operati di legamento crociato continuano ad avere dolore o limitazioni per anni. In uno studio su 184 persone, chi ha seguito quattro mesi di esercizi con un fisioterapista ha riferito un miglioramento maggiore di chi ha ricevuto una sola spiegazione con esercizi da fare da solo, e ha recuperato più forza nella coscia.", "Dopo un anno la differenza fra i due gruppi era più piccola, perché anche chi faceva gli esercizi da solo era migliorato: lo studio non dice se il vantaggio duri nel tempo."], "kw": "legamento crociato anteriore, fisioterapia dopo operazione, sintomi persistenti ginocchio"}, "2": {"prof": ["Altezza rotulea: Insall-Salvati e Caton-Deschamps affidabili in radiografia", "Sette chirurghi hanno misurato sette indici di altezza rotulea in 77 pazienti di un ospedale pediatrico: in radiografia l'ICC inter-osservatore è 0,69-0,82 per l'Insall-Salvati e 0,64-0,78 per il Caton-Deschamps, alla RM 0,88-0,92 per l'indice patello-trocleare; l'affidabilità non peggiora con l'immaturità scheletrica né con l'instabilità femoro-rotulea.", "Nota critica: serie retrospettiva da un solo ospedale, intervalli di confidenza degli ICC non riportati nell'abstract, e l'affidabilità non dimostra che un indice predica l'esito clinico."], "mix": ["Altezza della rotula: buon accordo fra chirurghi, non fra radiografia e risonanza", "Sette chirurghi hanno misurato in 77 giovani pazienti la posizione della rotula con sette indici diversi. In radiografia i due indici classici, Insall-Salvati e Caton-Deschamps, danno risultati sufficientemente concordi fra osservatori; alla risonanza l'indice patello-trocleare è il più coerente. Fra radiografia e risonanza, invece, solo l'Insall-Salvati resta ben confrontabile.", "Nota sul limite: lo studio misura quanto i medici si trovano d'accordo, non se un indice aiuti a scegliere l'intervento migliore; i dati vengono da un solo ospedale pediatrico."], "paz": ["Come si misura l'altezza della rotula: uno studio confronta gli indici usati dai chirurghi", "Quando la rotula tende a uscire dalla sua sede, i chirurghi ne valutano la posizione con misure sulla radiografia o sulla risonanza. Uno studio su 77 giovani pazienti ha verificato quanto sette diverse misure diano risultati simili quando le ripetono medici diversi.", "Le misure più usate risultano abbastanza affidabili, anche nei più giovani e in chi ha già avuto instabilità della rotula; lo studio però non dice quale misura porti alla scelta migliore per il singolo paziente."], "kw": "instabilità rotula, altezza rotulea, risonanza ginocchio"}, "3": {"prof": ["Sutura meniscale con coagulo midollare: nessuna differenza significativa con o senza cisti", "In una coorte retrospettiva di riparazioni meniscali aumentate con coagulo di fibrina da aspirato midollare, l'interazione gruppo per tempo non è significativa fra lesioni con e senza cisti meniscale né per l'IKDC (p=0,51) né per i criteri di Barrett (p=0,12) né per il segnale RM (p=0,86), con follow-up minimo di 12 mesi.", "Nota critica: il numero di pazienti non è riportato nell'abstract, quindi «nessuna differenza» non è prova di equivalenza, e manca un gruppo senza coagulo."], "mix": ["Sutura del menisco con coagulo di midollo: con o senza cisti, nessuna differenza a un anno", "Uno studio giapponese ha seguito per almeno un anno persone operate di sutura del menisco con l'aggiunta di un coagulo ricavato dal midollo osseo, confrontando chi aveva una cisti accanto al menisco e chi no. Le variazioni dei punteggi clinici e del segnale alla risonanza non sono risultate diverse in modo significativo fra i due gruppi.", "Nota sul limite: il numero dei pazienti non è indicato nel riassunto dello studio, per cui non si può dire quanto il confronto sarebbe stato in grado di rilevare una differenza."], "paz": ["Sutura del menisco: una cisti vicina non sembra peggiorare il risultato a un anno", "In uno studio su persone operate di sutura del menisco, con un coagulo ricavato dal loro midollo osseo aggiunto per favorire la guarigione, chi aveva una piccola cisti accanto al menisco non ha avuto risultati diversi da chi non l'aveva, a un anno di distanza.", "Il riassunto dello studio non indica quanti pazienti fossero e manca un gruppo operato senza il coagulo: è un'indicazione da confermare, non una certezza."], "kw": "sutura menisco, cisti meniscale, lesione del menisco"}, "4": {"prof": ["Deformità fisse in protesi robotica: minor resezione ossea associata a maggior recupero", "In 861 protesi con braccio robotico, di cui 227 con deformità fissa, un minor volume di resezione ossea si associa a un maggior miglioramento del KOOS JR a un anno nelle ginocchia non correggibili (p=0,016), e un maggior differenziale mediolaterale in flessione a un maggior miglioramento sia del KOOS JR (p=0,009) sia del PROMIS (p=0,044).", "Nota critica: coorte retrospettiva monocentrica, associazioni e non cause, piattaforma robotica non nominata e intervalli di confidenza non riportati nell'abstract."], "mix": ["Deformità fisse: meno osso rimosso e gap non forzati, recupero migliore a un anno", "Uno studio su 861 protesi di ginocchio eseguite con un braccio robotico indica che, nei ginocchi con una deformità che non si corregge a mano, chi ha avuto meno osso rimosso e ha mantenuto una parte della naturale asimmetria dei legamenti ha riferito un miglioramento maggiore della funzione a un anno.", "Nota sul limite: è uno studio retrospettivo di un solo centro, che mostra un'associazione e non dimostra che sia la scelta chirurgica a causare il risultato."], "paz": ["Protesi al ginocchio con deformità marcata: conservare più osso potrebbe aiutare il recupero", "In uno studio su 861 protesi di ginocchio, nei pazienti con una deformità che non si raddrizza a mano, chi ha avuto meno osso rimosso durante l'intervento ha riferito un miglioramento maggiore della funzione a un anno.", "È un'osservazione su pazienti già operati in un solo centro: mostra un legame, non dimostra che sia la quantità di osso rimosso a determinare il recupero."], "kw": "protesi ginocchio, deformità ginocchio, protesi robotica"}, "5": {"prof": ["Innesto del LCA con vancomicina: picco sierico 0,704 µg/mL, soglia tossica 15-20 µg/mL", "In una serie prospettica di 21 pazienti operati di ricostruzione del LCA con innesto (hamstring o quadricipite) imbevuto in vancomicina liquida, le concentrazioni sieriche mediane massime sono comparse a 6-24 ore (0,0050 µg/mL) e il massimo assoluto è stato 0,704 µg/mL; il tempo di imbibizione correla con il picco (r=0,497; p=0,022).", "Nota critica: 21 pazienti, misura la sicurezza sistemica e non la riduzione delle infezioni, concentrazione locale non riportata nell'abstract."], "mix": ["Innesto del crociato con antibiotico: nel sangue livelli molto sotto la soglia a rischio", "In 21 pazienti operati di legamento crociato con un innesto tenuto a bagno nell'antibiotico vancomicina, i livelli nel sangue dopo l'intervento sono rimasti molto al di sotto della soglia oltre la quale l'antibiotico può fare danni, con un massimo alcune ore dopo l'operazione. Più a lungo l'innesto restava a bagno, più alto risultava il livello.", "Nota sul limite: il gruppo è piccolo e lo studio verifica la sicurezza, non se il bagno antibiotico riduca davvero le infezioni."], "paz": ["Legamento crociato: l'antibiotico sull'innesto passa nel sangue in quantità molto basse", "Durante alcune operazioni di legamento crociato il nuovo legamento viene tenuto a bagno in un antibiotico prima di essere posizionato. In uno studio su 21 pazienti, la quantità dell'antibiotico trovata nel sangue nei due giorni successivi è rimasta molto al di sotto del livello considerato a rischio.", "Lo studio riguarda la sicurezza e un piccolo numero di persone: non dice se questo accorgimento riduca le infezioni."], "kw": "legamento crociato, infezione dopo operazione, vancomicina"}, "6": {"prof": ["A-ACI su difetti condrali grandi: membrana o periostio, esiti clinici simili a 2 anni", "In uno studio sequenziale non randomizzato (13 contro 13) sull'impianto di condrociti autologhi con atelocollagene, i punteggi clinici a 24 mesi non differiscono fra copertura con membrana di collagene e con periostio; il MOCART 2.0 è più alto con la membrana (83 contro 60; p=0,001) e le complicanze differiscono (ipertrofia o delaminazione 46% contro cisti subcondrali 15%).", "Nota critica: non randomizzato, 13 per gruppo, valutazioni strutturali dichiarate esplorative dagli autori, aggiustamento limitato per l'osteotomia concomitante."], "mix": ["Cartilagine del ginocchio: periostio o membrana, risultati clinici simili a due anni", "In uno studio giapponese su 26 casi di lesioni grandi della cartilagine trattate con cellule della cartilagine coltivate, la copertura dell'impianto con una membrana di collagene o con il periostio ha dato miglioramenti clinici simili a due anni. All'esame con risonanza la membrana ha ottenuto un punteggio più alto, ma le complicanze sono state di tipo diverso nei due gruppi.", "Nota sul limite: i gruppi sono piccoli e non assegnati per sorteggio, e gli stessi autori considerano le valutazioni di risonanza e istologia come esplorative."], "paz": ["Cartilagine con cellule coltivate: la copertura scelta non cambia il risultato a due anni", "Nelle lesioni grandi della cartilagine del ginocchio si possono impiantare cellule coltivate a partire dalla cartilagine stessa del paziente e coprirle con un sottile strato di tessuto o con una membrana. In uno studio su 26 casi, dopo due anni chi aveva l'una o l'altra copertura stava meglio in modo simile.", "Alla risonanza il risultato sembrava più regolare con la membrana, ma i gruppi erano piccoli e i pazienti non erano stati assegnati per sorteggio: è un'indicazione da confermare."], "kw": "cartilagine ginocchio, impianto di condrociti, lesione cartilaginea"}, "7": {"prof": ["Lesioni del midollo osseo del ginocchio: trattamenti chirurgici, evidenza ancora subottimale", "Una rassegna di esperti (livello V) passa in rassegna le opzioni chirurgiche dopo il fallimento del trattamento conservativo per le lesioni del midollo osseo del ginocchio: iniezioni intraossee con fosfato di calcio, PRP o cellule stromali mesenchimali, procedure di scarico e impianti meniscali.", "Nota critica: rassegna narrativa senza dati quantitativi nell'abstract; gli autori riferiscono buoni risultati ma evidenza subottimale e nessun approccio migliore identificato."], "mix": ["Lesioni del midollo osseo del ginocchio: che cosa si può fare quando le cure non bastano", "Un gruppo di esperti internazionali ha riassunto le opzioni chirurgiche per le lesioni del midollo osseo del ginocchio, visibili alla risonanza magnetica come un'area di segnale alterato: iniezioni dentro l'osso, procedure che scaricano l'articolazione e impianti al posto del menisco.", "Nota sul limite: è un'opinione di esperti e non un confronto fra trattamenti; gli autori stessi indicano che l'evidenza è ancora debole."], "paz": ["Macchie alla risonanza nell'osso del ginocchio: una rassegna sui trattamenti chirurgici", "Alla risonanza magnetica del ginocchio compaiono spesso aree di osso con un segnale alterato, che possono dare dolore. Quando le cure senza intervento non bastano, esistono procedure chirurgiche, come iniezioni dentro l'osso o operazioni che scaricano l'articolazione, riassunte in una rassegna di esperti.", "Gli autori precisano che le prove a sostegno di ciascun trattamento sono ancora deboli: la scelta si discute caso per caso con il chirurgo."], "kw": "edema osseo ginocchio, lesione midollo osseo, risonanza ginocchio"}, "8": {"prof": ["Dopo il LCA la scarica delle unità motorie non predice in modo coerente la forza a sei mesi", "In una coorte prospettica di 27 partecipanti con analisi bayesiana, la frequenza di scarica sottomassimale delle unità motorie del quadricipite, dal preoperatorio a tre mesi dopo il LCA, non si associa in modo coerente alla forza di estensione a sei mesi; a due settimane nell'arto operato +45,8 N per DS (intervallo di credibilità 95% da -18,5 a 114,6 N).", "Nota critica: 27 partecipanti, molti confronti, elettromiografia di superficie come stima indiretta, nessun esito clinico e tipo di innesto non riportato."], "mix": ["Dopo il crociato, l'attività muscolare precoce non anticipa con certezza la forza a sei mesi", "In 27 persone operate di legamento crociato, è stata registrata dall'esterno l'attività elettrica dei muscoli della coscia prima dell'intervento e nei primi tre mesi. Il ritmo con cui le unità motorie si attivano non ha previsto in modo coerente la forza dell'estensione del ginocchio misurata a sei mesi; solo a due settimane nel ginocchio operato compare un accenno, con ampia incertezza.", "Nota sul limite: il gruppo è piccolo, la misura è indiretta e lo studio non valuta il rientro allo sport né le nuove rotture."], "paz": ["Crociato: l'attività dei muscoli misurata presto non basta a prevedere la forza a sei mesi", "In uno studio su 27 persone operate di legamento crociato, un esame che registra l'attività elettrica dei muscoli della coscia nelle prime settimane non ha permesso di prevedere in modo affidabile quanta forza avrebbero avuto sei mesi dopo.", "Il gruppo era piccolo e lo studio non riguarda il ritorno allo sport: la forza va misurata direttamente più avanti nel recupero."], "kw": "legamento crociato, forza quadricipite, recupero dopo operazione"}, "9": {"prof": ["Robot OSR-2000 nella protesi di ginocchio: allineamento più accurato, complicanze non distinte", "In una coorte retrospettiva monocentrica di 86 protesi totali (43 contro 43) il robot OSR-2000 riduce la deviazione HKA e le deviazioni angolari dei componenti (tutti p<0,001) e dà un KSS più alto a 12 mesi (p=0,004), con tempo operatorio più lungo; le complicanze a 12 mesi (2/43 contro 6/43) non differiscono (p=0,265).", "Nota critica: retrospettivo, gruppi non randomizzati, pochi eventi per concludere sulla sicurezza, allineamento radiografico come esito surrogato."], "mix": ["Protesi di ginocchio con robot cinese: allineamento più preciso, operazione più lunga", "In uno studio su 86 pazienti operati di protesi totale di ginocchio, l'uso del robot OSR-2000 ha dato un allineamento della gamba più preciso e meno perdita di sangue rispetto alla tecnica manuale; a un anno il punteggio funzionale era più alto, mentre la mobilità e le complicanze non erano diverse in modo significativo.", "Nota sul limite: lo studio è retrospettivo e di un solo centro, con pochi eventi per giudicare la sicurezza; l'allineamento non equivale a un risultato clinico duraturo."], "paz": ["Protesi di ginocchio con robot: gamba meglio allineata in uno studio cinese", "Uno studio su 86 pazienti ha confrontato la protesi di ginocchio eseguita con un sistema robotico cinese e quella eseguita in modo tradizionale: con il robot la gamba risultava meglio allineata e si perdeva meno sangue, ma l'operazione durava di più.", "Dopo un anno le complicanze non erano diverse in modo significativo; lo studio è piccolo e retrospettivo, quindi non permette di trarre conclusioni definitive."], "kw": "protesi ginocchio, chirurgia robotica, artrosi ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Annals of Internal Medicine",h:"Dopo il LCA con sintomi persistenti, l'esercizio supervisionato aiuta a 4 mesi",v:"RCT su 184 giovani adulti con problemi persistenti 9-36 mesi dopo il LCA: a 4 mesi il KOOS migliora di 4,8 punti in più (IC 95% 1,4-8,2) con esercizio supervisionato rispetto a una sola sessione educativa; a 12 mesi il divario si riduce.",ax:"Culvenor, Bruder, West, Barton, Roos, Oei, McPhail, Souza, Lee, Patterson, Girdwood, Couch, Scholes, Crossley",date:"set 2026",meta:"RCT a gruppi paralleli non in cieco, 184 giovani adulti, 9-36 mesi dopo LCA · [II]",pmid:'42804769',doi:'10.7326/ANNALS-26-02460',journal:"Annals of internal medicine",authors:"Culvenor AG, Bruder AM, West TJ, Barton CJ, Roos EM, Oei EH, McPhail SM, Souza RB, Lee J, Patterson BE, Girdwood MA, Couch JL, Scholes MJ, Crossley KM",design:"Studio randomizzato a gruppi paralleli, in comunità (registro ACTRN12620001164987): 184 giovani adulti (18-40 anni) con problemi persistenti del ginocchio 9-36 mesi dopo la ricostruzione del LCA, 92 per braccio. Braccio SUPER: 4 mesi di esercizio terapeutico supervisionato dal fisioterapista due volte a settimana con educazione. Controllo: una sola sessione di educazione erogata dal fisioterapista più una risorsa di esercizio autogestito. Esito primario: variazione a 4 mesi del KOOS composito (0 = peggiore, 100 = migliore). Secondari: KOOS a 12 mesi, forza muscolare della coscia, valutazione globale di cambiamento percepita dal paziente, spessore e composizione della cartilagine alla RM a 4 e 12 mesi.",pop:"184 giovani adulti (età media 30 anni, DS 6), a 2,2 anni (DS 0,7) dalla ricostruzione; 92 per braccio; 178 (97%) e 174 (95%) hanno completato il follow-up a 4 e a 12 mesi.",results:"KOOS a 4 mesi: miglioramento di 14,1 punti con SUPER contro 9,4 nel controllo (differenza media aggiustata 4,8; IC 95% 1,4-8,2). A 4 mesi guadagni di forza muscolare maggiori e più successi alla valutazione globale di cambiamento con SUPER (ad esempio per il dolore 73% contro 40%). A 12 mesi le differenze fra i gruppi si riducono, perché il gruppo di controllo continua a migliorare mentre i guadagni di SUPER si mantengono; nessuna differenza nello spessore o nella composizione della cartilagine alla RM. Intervalli di confidenza per gli esiti secondari e per il KOOS a 12 mesi non riportati nell'abstract.",concl:"Gli autori concludono che, per i giovani adulti con problemi persistenti dopo il LCA, l'esercizio terapeutico supervisionato con educazione ha migliorato gli esiti riferiti dal paziente rispetto a una singola sessione educativa con esercizio autogestito, ma che le differenze fra i gruppi potrebbero non mantenersi nel tempo.",limits:"Partecipanti non in cieco (dichiarato dagli autori) ed esito primario riferito dal paziente · a 4 mesi la differenza di 4,8 punti ha un IC ampio (1,4-8,2): il limite inferiore è basso sulla scala 0-100 e l'abstract non dice se la soglia di rilevanza clinica sia superata · tipo di innesto della ricostruzione non riportato nell'abstract · articolo non open access: testo completo non aperto, numeri e limiti da abstract.",perte:"Non sono pazienti da operare ma pazienti già operati, con sintomi persistenti; e l'abstract non dice quanti avessero un innesto quadricipitale o di retto femorale. Tocca però il punto che T3 tiene aperto: quanto il deficit del quadricipite dopo il LCA pesi ben oltre i sei mesi. Qui la forza muscolare cresce di più con il programma supervisionato, e il vantaggio a 12 mesi si assottiglia perché anche il controllo migliora col tempo: non è una dimostrazione che il rinforzo tardivo cambi il destino dell'articolazione, la cartilagine alla RM non differisce."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"L'altezza rotulea: Insall-Salvati e Caton-Deschamps i più affidabili in radiografia",v:"Sette chirurghi, sette indici, 77 pazienti: alla RM il più riproducibile è l'indice patello-trocleare; né l'immaturità scheletrica né l'instabilità femoro-rotulea degradano l'affidabilità.",ax:"Kebeh, Kell, Orellana, Sarkar, Schlechter, Redler, Waldron, Kuba, Bixby, Crawford, Logterman, Veerkamp, Parikh, Williams",date:"set 2026",meta:"studio diagnostico di affidabilità, serie retrospettiva, 77 pazienti, ospedale pediatrico · [III]",pmid:'42803638',doi:'10.1002/arj.70465',journal:"Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association",authors:"Kebeh M, Kell D, Orellana KJ, Sarkar S, Schlechter JA, Redler LH, Waldron S, Kuba MHM, Bixby EC, Crawford EA, Logterman SL, Veerkamp MW, Parikh SN, Williams BA",design:"Serie di casi diagnostica retrospettiva da un database radiologico di un ospedale pediatrico (radiografie laterali del ginocchio e RM), costruito con analisi di potenza a priori. Sette chirurghi ortopedici con fellowship hanno misurato sette indici di altezza rotulea (Insall-Salvati, Caton-Deschamps, Blackburne-Peel, Knee Triangular Ratio, Insall-Salvati modificato, Koshino, indice patello-trocleare). Affidabilità inter- e intra-osservatore con coefficiente di correlazione intraclasse (ICC), sulle radiografie, sulla RM e fra le due modalità; confronti per maturità scheletrica e diagnosi di instabilità femoro-rotulea con test di Wilcoxon.",pop:"77 soggetti: 29 (37,7%) scheletricamente immaturi, 37 (48,1%) con diagnosi di instabilità femoro-rotulea.",results:"Radiografia: Insall-Salvati, ICC inter-osservatore 0,69-0,82 e intra-osservatore 0,75-0,95; Caton-Deschamps, inter 0,64-0,78 e intra 0,65-0,78. RM: indice patello-trocleare, inter 0,88-0,92 e intra 0,89-0,93. Fra radiografia e RM tutti gli indici tranne l'Insall-Salvati (0,65-0,73) hanno affidabilità dubbia o inaccettabile. L'affidabilità radiografica è maggiore nei pazienti con instabilità (inter-osservatore p<0,001; intra-osservatore p=0,035); alla RM l'affidabilità è maggiore negli uomini che nelle donne (inter p=0,007; intra p<0,001). Intervalli di confidenza degli ICC non riportati nell'abstract.",concl:"Gli autori concludono che Insall-Salvati e Caton-Deschamps sono gli indici più affidabili in radiografia, che alla RM l'indice patello-trocleare è il più costantemente affidabile (Insall-Salvati e Caton-Deschamps da molto buoni a eccellenti), che l'Insall-Salvati è l'unico con affidabilità molto buona fra le due modalità, e che né l'immaturità scheletrica né l'instabilità femoro-rotulea riducono l'affidabilità.",limits:"Serie retrospettiva da un solo ospedale pediatrico (livello III), 77 soggetti · misura l'accordo fra osservatori, non se un indice predica l'esito della stabilizzazione: affidabilità non è validità · nessun esito clinico · le differenze fra uomini e donne sono osservate ma non spiegate nell'abstract · testo completo non aperto.",perte:"Popolazione pediatrico-adolescenziale con instabilità e non la tua casistica adulta, ma tocca i tuoi casi di MPFL: se l'altezza rotulea orienta la scelta del gesto associato, l'indice e la modalità (radiografia o RM) non sono intercambiabili — l'unico indice affidabile fra le due modalità è l'Insall-Salvati. Va letto insieme al commento editoriale uscito nello stesso numero di Arthroscopy («meglio tenerla semplice»), fra i brevi di oggi."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"International Orthopaedics",h:"Riparazione meniscale con coagulo midollare: nessuna differenza rilevata con cisti meniscale",v:"Coorte retrospettiva: le variazioni di IKDC, criteri di Barrett e segnale RM a 12 mesi non differiscono in modo significativo fra lesioni con e senza cisti (p=0,51; 0,12; 0,86); numerosità non riportata nell'abstract.",ax:"Tsumoto, Nishino, Kishi, Iida, Terai, Hashimoto",date:"set 2026",meta:"coorte retrospettiva comparativa, numerosità non riportata nell'abstract, follow-up minimo 12 mesi · [III]",pmid:'42803959',doi:'10.1007/s00264-026-07046-0',journal:"International orthopaedics",authors:"Tsumoto S, Nishino K, Kishi H, Iida K, Terai H, Hashimoto Y",design:"Studio retrospettivo di pazienti sottoposti a riparazione meniscale con aumentazione mediante coagulo di fibrina derivato da aspirato di midollo osseo (BMA), follow-up minimo 12 mesi, divisi in gruppo con cisti meniscale e gruppo senza cisti. Valutati IKDC, criteri di Barrett e quoziente segnale-rumore (SNQ) alla RM prima dell'intervento e a 12 mesi; analisi dell'interazione gruppo per tempo.",pop:"Pazienti con riparazione meniscale aumentata con coagulo da BMA, con e senza cisti meniscale; numero di pazienti e di ginocchia non riportato nell'abstract.",results:"Interazione gruppo per tempo non significativa per l'IKDC (p=0,51), per i criteri di Barrett (p=0,12) e per il quoziente segnale-rumore alla RM (p=0,86). Valori assoluti, dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che la presenza di una cisti meniscale non ha prodotto una differenza statisticamente significativa nei cambiamenti longitudinali degli esiti clinici o RM dopo riparazione meniscale con coagulo da BMA.",limits:"Retrospettivo, numerosità non riportata nell'abstract: «nessuna differenza» non è prova di equivalenza · nessun gruppo di controllo senza coagulo: non dice se il coagulo da BMA aggiunga qualcosa alla sutura · tipo e sede di lesione e tecnica di sutura non riportati nell'abstract · testo completo non aperto.",perte:"Non è la radice meniscale: riguarda riparazioni con aumentazione biologica, in lesioni con o senza cisti, senza specificarne la sede. Utile per chi si chiede se una cisti cambi la prognosi della sutura, ma la risposta onesta è «non si sa»: il numero di pazienti non è nell'abstract, quindi non si può valutare quanto il confronto sia in grado di escludere una differenza."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"The Journal of Arthroplasty",h:"Protesi con deformità fissa: inseguire gap simmetrici si associa a recupero peggiore",v:"861 protesi di ginocchio con braccio robotico, 227 con deformità fissa: in queste, minor resezione ossea totale si associa a maggior miglioramento del KOOS JR a un anno (p=0,016).",ax:"Suhardi, Gwam, DiGangi, Hepinstall, Rozell, Meftah",date:"set 2026",meta:"coorte retrospettiva monocentrica su casi consecutivi, 861 protesi con braccio robotico (227 deformità fisse) · [III]",pmid:'42805272',doi:'10.1016/j.arth.2026.09.011',journal:"The Journal of arthroplasty",authors:"Suhardi VJ, Gwam C, DiGangi C, Hepinstall M, Rozell J, Meftah M",design:"Coorte retrospettiva monocentrica, in un centro accademico, di 861 artroprotesi totali primarie di ginocchio consecutive con assistenza robotica (634 correggibili, 227 non correggibili). Correggibilità valutata in sala con stress in varo-valgo in estensione: correggibile se l'allineamento arriva entro 3° dal neutro. Il sistema robotico ha quantificato la lassità nativa e ricostruita dei compartimenti in quasi-estensione (5-20°) e in flessione (90±10°) e registrato le profondità di resezione pianificate. Differenziale mediolaterale postoperatorio (mediale meno laterale) classificato in simmetrico (<0,5 mm), parzialmente corretto (0,5-2 mm) e asimmetria nativa preservata (2-5 mm). Esiti: KOOS JR e PROMIS Physical Function a 6 settimane, 3 mesi e 1 anno.",pop:"861 protesi in un solo centro: 634 ginocchia correggibili e 227 non correggibili.",results:"Nelle ginocchia non correggibili il miglioramento del PROMIS Physical Function è maggiore a 3 mesi (p=0,003) e a 1 anno (7,0±7,8 contro 4,9±6,8; p=0,036), a parità di punteggi preoperatori. Fra le non correggibili, un minor volume totale di resezione ossea si associa a un maggior miglioramento del KOOS JR a 1 anno (p=0,016), con l'associazione più forte nel compartimento laterale in flessione (p=0,039); un maggior differenziale mediolaterale in flessione si associa a un maggior miglioramento sia del KOOS JR (p=0,009) sia del PROMIS (p=0,044). Coefficienti di regressione e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che, nelle ginocchia non correggibili operate con assistenza robotica, la preservazione dell'asimmetria nativa della lassità mediolaterale si associa a un recupero funzionale riferito dal paziente superiore, e che i risultati mettono in discussione l'obiettivo universale dei gap simmetrici a favore di una strategia adattativa che privilegia la conservazione ossea.",limits:"Coorte retrospettiva monocentrica: associazioni, non cause: la scelta di resecare meno o di tollerare l'asimmetria non è randomizzata e può dipendere dal ginocchio e dal chirurgo · un anno di follow-up · esiti riferiti dal paziente senza intervalli di confidenza né dimensioni dell'effetto nell'abstract · piattaforma robotica non nominata nell'abstract · sopravvivenza dell'impianto non riportata come esito · testo completo non aperto.",perte:"Riguarda la tua protesi robotica: il dato suggerisce che, in una deformità fissa, togliere più osso per pareggiare i gap si associa a un recupero peggiore, un argomento da tenere presente quando con la VELYS decidi fino a che punto correggere la lassità. Ma la piattaforma dello studio non è nominata nell'abstract e un'associazione non è una dimostrazione di causa."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"LCA e vancomicina sull'innesto: livelli sierici ben sotto la soglia tossica",v:"Serie prospettica di 21 pazienti: il massimo sierico osservato in tutti i campioni è 0,704 µg/mL, contro una soglia tossica di 15-20 µg/mL; picchi mediani fra 6 e 24 ore.",ax:"Witteveen, Ubl, Krombholz, Guenther, Flieser, Wafaisade, Bouillon, Thevis, Pfeiffer",date:"set 2026",meta:"serie di casi prospettica, 21 pazienti · [IV]",pmid:'42803685',doi:'10.1002/arj.70606',journal:"Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association",authors:"Witteveen S, Ubl ST, Krombholz S, Guenther D, Flieser C, Wafaisade A, Bouillon B, Thevis M, Pfeiffer TR",design:"Serie di casi prospettica (livello IV) su pazienti consenzienti fra ottobre 2023 e gennaio 2024, sottoposti a ricostruzione isolata del LCA o a revisione in due tempi dopo innesto osseo dei tunnel. Innesti di hamstring o di quadricipite, con o senza chirurgia meniscale, imbevuti in vancomicina liquida (tempo di imbibizione misurato). Sei prelievi di sangue: preoperatorio, 10 minuti dopo il rilascio del laccio, 1 ora, 6-8 ore, 24 ore e 48 ore. Vancomicina misurata con spettrometria di massa tandem e cromatografia liquida ad alte prestazioni; correlazioni di Spearman.",pop:"21 pazienti (17 uomini, 4 donne; età mediana 36 anni, IQR 16).",results:"Concentrazioni sieriche mediane massime a 6-8 ore (0,0050 µg/mL; IQR 0,0079) e a 24 ore (0,0050 µg/mL; IQR 0,0144); a 48 ore ancora rilevabile (0,0021 µg/mL; IQR 0,0032). Massimo assoluto in tutti i campioni: 0,704 µg/mL, contro una soglia tossica di 15-20 µg/mL. Correlazione fra tempo di imbibizione e concentrazione sierica massima: r=0,497 (p=0,022); intervallo di confidenza non riportato nell'abstract.",concl:"Gli autori concludono che le concentrazioni sistemiche dopo l'impianto di un innesto del LCA imbevuto di vancomicina liquida restano ben al di sotto della soglia tossica per gli eventi avversi, con picchi fra 6 e 24 ore dall'intervento, e che il tempo di imbibizione influenza in modo significativo i livelli sistemici.",limits:"Serie di soli 21 pazienti (livello IV): una tossicità rara non è stimabile · misura la sicurezza sistemica (livelli nel sangue), non l'efficacia nel prevenire l'infezione del sito chirurgico · concentrazione locale nell'articolazione non riportata nell'abstract · innesti di hamstring e di quadricipite non analizzati separatamente nell'abstract · testo completo non aperto.",perte:"Se imbibisci l'innesto in vancomicina, o lo consideri, questo è un dato di sicurezza sistemica che comprende anche innesti di quadricipite (senza analisi separata nell'abstract). Non risponde alla domanda che conta di più, se l'imbibizione riduca le infezioni: è una risposta sulla sicurezza, non sull'efficacia."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Experimental Orthopaedics",h:"A-ACI: periostio o membrana di collagene, esiti clinici simili a due anni",v:"Studio sequenziale non randomizzato, 13 contro 13 lesioni condrali grandi: MOCART 2.0 più alto con la membrana a 24 mesi (83 contro 60; p=0,001); esiti clinici senza differenze significative.",ax:"Kaibara, Kondo, Ogawa, Matsuoka, Iwasaki, Onodera, Oda, Tanei, Momma, Tanaka, Yasuda, Yagi, Iwasaki",date:"set 2026",meta:"studio comparativo non randomizzato sequenziale, 13 contro 13, follow-up minimo 24 mesi · [III]",pmid:'42799521',doi:'10.1002/jeo2.70924',journal:"Journal of experimental orthopaedics",authors:"Kaibara T, Kondo E, Ogawa Y, Matsuoka M, Iwasaki K, Onodera T, Oda Y, Tanei ZI, Momma D, Tanaka S, Yasuda K, Yagi T, Iwasaki N",design:"Studio comparativo sequenziale non randomizzato, 2014-2022: impianto di condrociti autologhi associato ad atelocollagene (A-ACI) con copertura periostale (n=13) o con membrana di collagene (n=13) per difetti condrali a tutto spessore di grandi dimensioni (soglia riportata: ≥4,0 cm). Esiti a 12 e 24 mesi: Lysholm, KOOS e MOCART 2.0 alla RM; second look artroscopico con punteggi ICRS e Oswestry Arthroscopy Score (OAS); istologia con ICRS II. Follow-up minimo 24 mesi; aggiustamento limitato per osteotomia concomitante.",pop:"13 con copertura periostale e 13 con membrana di collagene (l'abstract non specifica se l'unità sia il paziente o il ginocchio).",results:"Miglioramento clinico significativo a 24 mesi in entrambi i gruppi, senza differenze significative fra i gruppi (valori di Lysholm e KOOS non riportati nell'abstract). MOCART 2.0 più alto con la membrana di collagene a 12 e a 24 mesi (83 contro 60 a 24 mesi; p=0,001); OAS 8,5 contro 6,7 (p=0,034); punteggi ICRS comparabili; parametri istologici (morfologia del tessuto, integrazione basale, osso subcondrale) superiori con la membrana. Complicanze: ipertrofia dell'innesto e delaminazione nel gruppo periostale (46%) contro cisti ossee subcondrali nel gruppo con membrana (15%). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che gli esiti clinici primari sono migliorati in modo simile in entrambi i gruppi, senza superiorità significativa di uno dei due, che la copertura con membrana di collagene resta associata a MOCART 2.0 più alto dopo un aggiustamento limitato per osteotomia concomitante, e che tutte le valutazioni strutturali vanno considerate strettamente secondarie ed esplorative.",limits:"Non randomizzato e sequenziale (livello III): confondimento per periodo e per curva di apprendimento · 13 per gruppo · valutazioni strutturali dichiarate esplorative dagli autori · complicanze diverse nei due gruppi (ipertrofia e delaminazione contro cisti subcondrali) su numeri minimi · osteotomia concomitante come fattore di confondimento, con aggiustamento limitato · testo completo non aperto.",perte:"Non è né AMIC né minced cartilage: sono condrociti autologhi coltivati, tecnica diversa dalla tua. Ma la membrana di collagene come copertura richiama il principio dell'AMIC, e il quesito, quale copertura dia un tessuto di riparazione più regolare, è affine. Il dato solido è solo che i risultati clinici non si distinguono a due anni; la differenza alla RM va letta come ipotesi."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Lesioni midollari del ginocchio: i trattamenti chirurgici non hanno ancora evidenza solida",v:"Rassegna di esperti (Andriolo, Sangiorgio, Brittberg, Kon, Filardo e altri) sulle opzioni chirurgiche per le lesioni del midollo osseo: iniezioni intraossee, procedure di scarico, impianti meniscali; buoni risultati riportati, evidenza ancora subottimale.",ax:"Andriolo, Sangiorgio, Brittberg, Condello, Farr, Kon, Levy, Filardo",date:"set 2026",meta:"revisione narrativa di esperti · [V]",pmid:'42799511',doi:'10.1002/jeo2.70249',journal:"Journal of experimental orthopaedics",authors:"Andriolo L, Sangiorgio A, Brittberg M, Condello V, Farr J, Kon E, Levy AS, Filardo G",design:"Rassegna narrativa (livello V, opinione di esperti) sui trattamenti chirurgici delle lesioni del midollo osseo (BML) del ginocchio, da considerare dopo il fallimento del trattamento non operatorio: iniezioni intraossee con biomateriali (fosfato di calcio) o con ortobiologici (plasma ricco di piastrine, cellule stromali mesenchimali), procedure di scarico e impianti meniscali. Le cause elencate comprendono lesioni traumatiche, artrosi, fratture da insufficienza subcondrale e osteonecrosi. Metodo di ricerca della letteratura non riportato nell'abstract.",pop:"Non applicabile: rassegna narrativa; numero di studi e di pazienti non riportato nell'abstract.",results:"Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract. Gli autori riferiscono buoni risultati in letteratura per molte delle opzioni chirurgiche disponibili, ma un livello di evidenza ancora subottimale e nessun approccio migliore identificato.",concl:"Gli autori concludono che, dopo il fallimento del trattamento conservativo, esistono più opzioni chirurgiche con buoni risultati riportati, ma che il livello di evidenza resta subottimale e l'approccio migliore non è stato ancora identificato.",limits:"Revisione narrativa, opinione di esperti (livello V) · nessun dato quantitativo nell'abstract · cause molto eterogenee (traumatica, artrosica, insufficienza subcondrale, osteonecrosi) messe insieme · testo completo disponibile su PMC (PMC13614689) ma non aperto in questa sessione: giudizio dall'abstract.",perte:"Rientra nell'asse ICRS che conta per te: Andriolo (Rizzoli), Kon (Humanitas), Filardo, con Sangiorgio dell'EOC di Lugano. Ma le lesioni del midollo osseo non sono le tue tecniche primarie (LET, radice meniscale, minced cartilage): sono procedure di preservazione articolare adiacenti, senza dati per la tua casistica."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Annals of Medicine",h:"Unità motorie dopo LCA: predittore incoerente della forza a sei mesi",v:"Coorte prospettica di 27 partecipanti con analisi bayesiana: la frequenza di scarica delle unità motorie del quadricipite non si associa in modo coerente alla forza di estensione a sei mesi; un accenno solo nell'arto operato a due settimane, con intervallo di credibilità che include lo zero.",ax:"Buhmann, Reeves, Mellifont, Stuelcken, Sayers, Borg, Lawrie",date:"set 2026",meta:"coorte prospettica longitudinale, 27 partecipanti, analisi bayesiana · [III]",pmid:'42804596',doi:'10.1080/07853890.2026.2740295',journal:"Annals of medicine",authors:"Buhmann R, Reeves A, Mellifont D, Stuelcken M, Sayers M, Borg DN, Lawrie S",design:"Studio longitudinale prospettico: 27 partecipanti (15 donne) con elettromiografia di superficie del vasto mediale e del vasto laterale durante estensione isometrica sottomassimale del ginocchio, dal preoperatorio a tre mesi dopo la ricostruzione del LCA. Forza massima volontaria isometrica di estensione a sei mesi modellata con regressione bayesiana e interpretata con una regione di equivalenza pratica (ROPE, ±15 N); analisi gerarchica secondaria fra ampiezza del potenziale d'azione dell'unità motoria (MUAP) e frequenza di scarica.",pop:"27 partecipanti (15 donne) sottoposti a ricostruzione del LCA; tipo di innesto non riportato nell'abstract.",results:"La frequenza di scarica non è associata in modo coerente alla forza a sei mesi fra tempi e arti. Nell'arto ricostruito a due settimane, +1 DS di frequenza media di scarica si associa a +45,8 N di forza a sei mesi (intervallo di credibilità 95% da -18,5 a 114,6 N, compatibile con nessun effetto). Forza a sei mesi maggiore nell'arto controlaterale (198,4 N; intervallo di credibilità 95% 171,6-225,1), nei maschi (184,3 N; 32,0-325,1) e con maggiore massa corporea (119,9 N per DS; 33,4-207,2). Maggiore ampiezza relativa del MUAP associata a minore frequenza di scarica (-3,7 Hz per DS; -3,8/-3,6).",concl:"Gli autori concludono che la frequenza di scarica sottomassimale delle unità motorie non è coerentemente associata alla forza estensoria successiva, pur suggerendo un'associazione positiva più forte nell'arto ricostruito a due settimane, e che il suo valore predittivo appare limitato.",limits:"27 partecipanti e molti confronti (tempi per arti): rischio di associazioni casuali · elettromiografia di superficie, stima indiretta delle unità motorie · nessun esito clinico (rientro allo sport, rirottura) · tipo di innesto non riportato nell'abstract · l'intervallo di credibilità dell'associazione a due settimane include lo zero · testo completo non aperto.",perte:"Non è il tuo innesto (tipo non riportato) né un test da ambulatorio: l'elettromiografia di superficie non è di routine. Va però nella direzione di T3: prevedere il deficit del quadricipite a sei mesi da ciò che accade nelle prime settimane non è ancora possibile con questo strumento, quindi la misura diretta della forza al momento del rientro resta necessaria."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Robotic Surgery",h:"Robot cinese OSR-2000 nella protesi di ginocchio: allineamento migliore, complicanze non distinte",v:"Coorte retrospettiva monocentrica di 86 protesi: scostamenti di allineamento minori con il robot (tutti p<0,001), KSS a 12 mesi più alto (p=0,004); complicanze 2/43 contro 6/43, non significative (p=0,265).",ax:"Xu, Zhang, Zeng, Wang, Cheng, Bao, Tian, Zhu, Jin, Zou",date:"set 2026",meta:"coorte retrospettiva monocentrica, 86 pazienti (43 contro 43), follow-up 12 mesi · [III]",pmid:'42801399',doi:'10.1007/s11701-026-03969-3',journal:"Journal of robotic surgery",authors:"Xu Y, Zhang J, Zeng Y, Wang H, Cheng F, Bao Y, Tian F, Zhu Z, Jin P, Zou L",design:"Coorte retrospettiva monocentrica di 86 pazienti con artrosi terminale unilaterale operati di protesi totale primaria fra marzo 2024 e marzo 2025, raggruppati secondo la tecnica effettivamente ricevuta: robot OSR-2000 (MicroPort ChangHang Robot, Suzhou; pianificazione 3D, navigazione ottica, osteotomia robotica vincolata) (n=43) o tecnica manuale convenzionale (n=43), con lo stesso sistema protesico posterostabilizzato. Esiti primari: deviazione HKA e deviazioni angolari coronali e sagittali dei componenti; secondari: parametri perioperatori, VAS, ROM e KSS a 1, 3 e 12 mesi, complicanze a 12 mesi. Test t, ANOVA per misure ripetute, test esatto di Fisher.",pop:"86 pazienti (43 robot, 43 manuale), stessa protesi posterostabilizzata; follow-up di 12 mesi.",results:"Con il robot: deviazione HKA e deviazioni angolari dei componenti minori (tutti p<0,001); tempo operatorio e di laccio maggiori (entrambi p<0,001); minore perdita ematica, drenaggio a 24 ore e calo di emoglobina (tutti p<0,001); VAS più bassa, ROM e KSS migliori a 1 e 3 mesi (p<0,05); a 12 mesi KSS ancora più alto (p=0,004), ROM non più differente (p=0,058). Degenza e complicanze non differenti: complicanze a 12 mesi 2/43 (4,65%) contro 6/43 (13,95%), test di Fisher a due code p=0,265. Nessun evento avverso legato al robot. Valori assoluti e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che il sistema OSR-2000 dà un impianto più accurato e un migliore allineamento dell'arto rispetto alla tecnica manuale, con minore perdita ematica e migliori sollievo dal dolore e funzione precoci, e lo definiscono un'alternativa sicura e precisa; richiedono studi multicentrici più ampi e a lungo termine e riconoscono che il tasso di complicanze numericamente più basso non ha raggiunto la significatività.",limits:"Retrospettivo monocentrico (livello III), gruppi formati secondo la tecnica ricevuta e non per randomizzazione: confondimento per selezione e per periodo · 43 per gruppo: 2 contro 6 complicanze sono troppo pochi eventi per concludere sulla sicurezza · 12 mesi di follow-up, nessun dato di sopravvivenza dell'impianto · l'allineamento radiografico non è un esito clinico · testo completo non aperto.",perte:"Piattaforma diversa dalla tua (OSR-2000, MicroPort ChangHang, Cina): non trasferisce nulla di diretto sulla VELYS. È coerente con la meta-analisi del 26 settembre (PMID 42789133) per il tempo operatorio più lungo; il vantaggio funzionale precoce che qui compare, invece, in quella meta-analisi non c'era, e un singolo studio retrospettivo non basta a confermarlo."}];
var SUGGQ=[{k:"kol",n:"Thomas Neri",w:"Hospices Civils de Lyon (Hôpital Lyon Sud), Francia — ultimo autore della nota tecnica di oggi sulla ricostruzione indipendente del legamento antero-laterale con gracile peduncolato; corrispondenza tecnica con il tuo rinforzo laterale sistematico (stesso obiettivo, il controllo della rotazione, con un gesto diverso dal Lemaire onlay). Sostituisce Francisco Endara Urresta (28 settembre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Il lavoro del giorno arriva dall'Australia e riguarda chi, anche uno o due anni dopo la ricostruzione del legamento crociato anteriore, continua ad avere sintomi al ginocchio. Uno studio randomizzato su centottantaquattro giovani adulti, pubblicato sugli Annals of Internal Medicine, ha confrontato quattro mesi di esercizio supervisionato dal fisioterapista, con educazione, contro una sola sessione informativa più un programma da fare da soli. A quattro mesi il punteggio KOOS migliora di quasi cinque punti in più con il programma supervisionato, con un intervallo di confidenza da uno virgola quattro a otto virgola due; la forza della coscia cresce di più e la cartilagine alla risonanza non cambia. A dodici mesi la differenza si riduce, perché anche il gruppo di controllo migliora, e i partecipanti non erano in cieco. Non sono pazienti da operare, e l'abstract non dice quale innesto fosse stato usato: ma è un dato utile sul deficit del quadricipite oltre i sei mesi.\n\nSullo stesso terreno, un secondo lavoro, piccolo, su ventisette pazienti, non trova che la frequenza di scarica delle unità motorie del quadricipite nelle prime settimane predica in modo coerente la forza a sei mesi: la misura diretta della forza al rientro resta necessaria.\n\nLe altre schede di oggi: una serie di ottocentosessantuno protesi con braccio robotico suggerisce che, nelle deformità fisse, togliere meno osso e non forzare gap simmetrici si associa a un recupero migliore, ma è un'associazione da un solo centro; uno studio sull'altezza rotulea indica Insall-Salvati e Caton-Deschamps come i più affidabili in radiografia e l'indice patello-trocleare alla risonanza; una coorte sulla riparazione meniscale con coagulo di midollo osseo non vede differenze fra lesioni con e senza cisti, ma senza il numero dei pazienti nell'abstract; una serie di ventuno pazienti mostra livelli sierici di vancomicina molto sotto la soglia tossica quando l'innesto del crociato viene imbevuto; uno studio piccolo e non randomizzato sull'impianto di condrociti non trova differenze cliniche a due anni fra copertura con periostio e con membrana; una rassegna di esperti dell'asse Bologna, Milano e Lugano sui trattamenti chirurgici delle lesioni del midollo osseo conclude che l'evidenza è ancora debole; e uno studio retrospettivo su un robot cinese per la protesi di ginocchio riporta un allineamento più accurato, con tempo operatorio più lungo e complicanze non distinte.\n\nNessun richiamo nuovo: i richiami del nucleo sorvegliato restano quelli già noti. Nessuna ritrattazione nuova sul citato. Due voci nuove fra le linee guida degli ultimi sessanta giorni riguardano la cartilagine della caviglia, fuori dal tuo perimetro. Nessuna tensione si è mossa oggi.";
var BRIEF_DIALOGO=[{chi:"A",t:"Il lavoro di oggi arriva dall'Australia: uno studio randomizzato su centottantaquattro giovani adulti che, da nove a trentasei mesi dopo la ricostruzione del crociato, hanno ancora sintomi al ginocchio."},{chi:"B",t:"Quindi non sono pazienti da operare, sono già operati. Che cosa hanno confrontato?"},{chi:"A",t:"Quattro mesi di esercizio supervisionato dal fisioterapista con educazione, contro una sola sessione informativa e un programma da fare da soli. A quattro mesi il KOOS migliora di quasi cinque punti in più con il programma supervisionato, con un intervallo di confidenza da uno virgola quattro a otto virgola due."},{chi:"B",t:"Cinque punti su cento non sono tantissimi. Regge nel tempo?"},{chi:"A",t:"A dodici mesi la differenza si riduce, perché anche il gruppo di controllo continua a migliorare. E i partecipanti non erano in cieco, con un esito riferito da loro. La forza della coscia cresce di più con il programma supervisionato, la cartilagine alla risonanza non cambia."},{chi:"B",t:"E per il tuo tendine quadricipitale? L'abstract lo dice?"},{chi:"A",t:"No, il tipo di innesto non è riportato. Ma tocca il punto di T3: il deficit del quadricipite conta ben oltre i sei mesi, e qui è un bersaglio trattabile. Non dimostra che il rinforzo tardivo cambi il destino dell'articolazione."},{chi:"B",t:"Sullo stesso tema c'è altro oggi?"},{chi:"A",t:"Uno studio piccolo, ventisette pazienti, non trova che la scarica delle unità motorie nelle prime settimane predica in modo coerente la forza a sei mesi. Quindi la misura diretta della forza al rientro resta necessaria."},{chi:"B",t:"Per la tua VELYS c'è qualcosa?"},{chi:"A",t:"Una serie di ottocentosessantuno protesi con braccio robotico: nelle deformità fisse togliere meno osso e non forzare gap simmetrici si associa a un recupero migliore. Ma è un solo centro, e un'associazione, non una causa. La piattaforma non è nominata nell'abstract."},{chi:"B",t:"E le altre schede?"},{chi:"A",t:"Altezza rotulea, con Insall-Salvati e Caton-Deschamps i più affidabili in radiografia; vancomicina sull'innesto del crociato con livelli nel sangue molto sotto la soglia tossica; e una rassegna dell'asse Bologna, Milano e Lugano sulle lesioni del midollo osseo, con evidenza ancora debole."},{chi:"B",t:"Industria e ritrattazioni?"},{chi:"A",t:"Nessun richiamo nuovo, nessuna ritrattazione nuova sul citato, e nessuna tensione si è mossa oggi."}];
